int compat_waitid(int which, compat_pid_t pid, struct compat_siginfo __user *infop,
                  int options, struct compat_rusage __user *uru)
{
    struct compat_siginfo si;
    struct rusage ru;
    int ret;

    ret = kernel_waitid(which, pid, &si, options, (struct rusage *) &ru);
    if (ret < 0)
        return ret;

    if (infop) {
        if (copy_to_user(infop, &si, sizeof(si)))
            return -EFAULT;
    }

