#include <linux/compat.h>
#include <linux/sched.h>
#include <linux/wait.h>

int compat_waitid_syscall(int which, compat_pid_t pid,
                          struct compat_siginfo __user *infop,
                          int options, struct compat_rusage __user *uru)
{
    struct waitid_info info;
    int ret;

    ret = kernel_waitid(which, pid, &info, options, uru);
    if (ret < 0)
        return ret;

    if (infop) {
        struct compat_siginfo si;

        compat_siginfo_to_user(&si, &info.si);
        if (copy_to_user(infop, &si, sizeof(si)))
            return -EFAULT;
    }

    return 0;
}
